using FluentValidation; using MediatR; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Caching.Distributed; using MSA.Contracts; using MSA.EventBusOutbox; using MSA.Infrastrucute.Mediator; using MSA.CatalogService.Domain; using MSA.CatalogService.Infrastructure; using System.Text.Json;
namespace MSA.CatalogService.Application;
public sealed record ProductDto(Guid Id, Guid CategoryId, string Sku, string Name, string Description, decimal Price, string Currency, bool IsActive, DateTimeOffset UpdatedOnUtc);
public sealed record GetProductQuery(Guid Id) : IQuery<ProductDto?>;
public sealed record CreateProductCommand(Guid CategoryId, string Sku, string Name, string Description, decimal Price, string Currency) : ICommand<Guid>;
public sealed record UpdateProductCommand(Guid Id,string Name,string Description,decimal Price,bool IsActive):ICommand<bool>;
public sealed record CreateCategoryCommand(string Name):ICommand<Guid>;
public sealed record ListProductsQuery(int Skip,int Take):IQuery<IReadOnlyList<ProductDto>>;
public sealed class CreateProductValidator : AbstractValidator<CreateProductCommand> { public CreateProductValidator() { RuleFor(x => x.CategoryId).NotEmpty(); RuleFor(x => x.Sku).NotEmpty().MaximumLength(80); RuleFor(x => x.Name).NotEmpty().MaximumLength(200); RuleFor(x => x.Price).GreaterThanOrEqualTo(0); RuleFor(x => x.Currency).Length(3); } }
public sealed class UpdateProductValidator:AbstractValidator<UpdateProductCommand>{public UpdateProductValidator(){RuleFor(x=>x.Id).NotEmpty();RuleFor(x=>x.Name).NotEmpty().MaximumLength(200);RuleFor(x=>x.Price).GreaterThanOrEqualTo(0);}}
public sealed class CreateCategoryValidator:AbstractValidator<CreateCategoryCommand>{public CreateCategoryValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(120);}}
internal sealed class GetProductHandler(CatalogDbContext db, IDistributedCache cache) : IRequestHandler<GetProductQuery, ProductDto?>
{
    public async Task<ProductDto?> Handle(GetProductQuery request, CancellationToken ct) { var key = $"catalog:product:{request.Id:N}"; var cached = await cache.GetStringAsync(key, ct); if (cached is not null) return JsonSerializer.Deserialize<ProductDto>(cached); var result = await db.Products.AsNoTracking().Where(x => x.Id == request.Id && x.IsActive).Select(x => new ProductDto(x.Id,x.CategoryId,x.Sku,x.Name,x.Description,x.Price,x.Currency,x.IsActive,x.UpdatedOnUtc)).SingleOrDefaultAsync(ct); if (result is not null) await cache.SetStringAsync(key, JsonSerializer.Serialize(result), new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5), SlidingExpiration = TimeSpan.FromMinutes(1) }, ct); return result; }
}
internal sealed class CreateProductHandler(CatalogDbContext db, IOutboxStore outbox) : IRequestHandler<CreateProductCommand, Guid>
{
    public async Task<Guid> Handle(CreateProductCommand r, CancellationToken ct) { if(!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId,ct))throw new KeyNotFoundException("Category not found.");var p = new Product(Guid.NewGuid(),r.CategoryId,r.Sku,r.Name,r.Description,r.Price,r.Currency); db.Products.Add(p); Publish(p);return p.Id; }private void Publish(Product p){var e = new ProductChangedIntegrationEvent { ProductId=p.Id,Sku=p.Sku,Name=p.Name,Price=p.Price,Currency=p.Currency,IsActive=p.IsActive }; outbox.Add(OutboxMessage.Create(e.GetType().AssemblyQualifiedName!,JsonSerializer.Serialize(e,e.GetType())));}
}
internal sealed class UpdateProductHandler(CatalogDbContext db,IOutboxStore outbox,IDistributedCache cache):IRequestHandler<UpdateProductCommand,bool>{public async Task<bool> Handle(UpdateProductCommand r,CancellationToken ct){var p=await db.Products.SingleOrDefaultAsync(x=>x.Id==r.Id,ct)??throw new KeyNotFoundException("Product not found.");p.Update(r.Name,r.Description,r.Price,r.IsActive);var e=new ProductChangedIntegrationEvent{ProductId=p.Id,Sku=p.Sku,Name=p.Name,Price=p.Price,Currency=p.Currency,IsActive=p.IsActive};outbox.Add(OutboxMessage.Create(e.GetType().AssemblyQualifiedName!,JsonSerializer.Serialize(e,e.GetType())));await cache.RemoveAsync($"catalog:product:{p.Id:N}",ct);return true;}}
internal sealed class CreateCategoryHandler(CatalogDbContext db):IRequestHandler<CreateCategoryCommand,Guid>{public Task<Guid> Handle(CreateCategoryCommand r,CancellationToken ct){var category=new Category(Guid.NewGuid(),r.Name);db.Categories.Add(category);return Task.FromResult(category.Id);}}
internal sealed class ListProductsHandler(CatalogDbContext db):IRequestHandler<ListProductsQuery,IReadOnlyList<ProductDto>>{public async Task<IReadOnlyList<ProductDto>> Handle(ListProductsQuery r,CancellationToken ct)=>await db.Products.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).Skip(Math.Max(0,r.Skip)).Take(Math.Clamp(r.Take,1,100)).Select(x=>new ProductDto(x.Id,x.CategoryId,x.Sku,x.Name,x.Description,x.Price,x.Currency,x.IsActive,x.UpdatedOnUtc)).ToListAsync(ct);}
